  {target:"Personal selling", c:"ps", sents:["Shine Water Purifiers advertises on TV.","It also offers 10% off in July.","Its trained staff visit homes, test the water and explain which model suits the family.","The company is based in Pune."], a:2, why:"Face-to-face presentation: <b>personal selling</b>."}
